changeSet.sql:
ALTER TABLE zc_referral
  ADD CONSTRAINT fk_zc_referral_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_referral
  ADD CONSTRAINT fk_zc_referral_enrolment FOREIGN KEY (tenant_id, enrolment_id, member_id)
    REFERENCES zc_enrolment (tenant_id, id, member_id);
ALTER TABLE zc_referral
  ADD CONSTRAINT fk_zc_referral_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);
ALTER TABLE zc_referral
  ADD CONSTRAINT fk_zc_referral_referral_type FOREIGN KEY (tenant_id, referral_type_id)
    REFERENCES zc_referral_type (tenant_id, id);
ALTER TABLE zc_referral
  ADD CONSTRAINT fk_zc_referral_receiving_org FOREIGN KEY (tenant_id, receiving_org_id)
    REFERENCES zc_organisation (tenant_id, id);

ALTER TABLE zc_transition
  ADD CONSTRAINT fk_zc_transition_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_transition
  ADD CONSTRAINT fk_zc_transition_enrolment FOREIGN KEY (tenant_id, enrolment_id)
    REFERENCES zc_enrolment (tenant_id, id);

ALTER TABLE zc_provider_participation
  ADD CONSTRAINT fk_zc_provider_participation_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_provider_participation
  ADD CONSTRAINT fk_zc_provider_participation_programme_version FOREIGN KEY (tenant_id, programme_version_id)
    REFERENCES zc_programme_version (tenant_id, id);
ALTER TABLE zc_provider_participation
  ADD CONSTRAINT fk_zc_provider_participation_organisation FOREIGN KEY (tenant_id, organisation_id)
    REFERENCES zc_organisation (tenant_id, id);

ALTER TABLE zc_provider_action
  ADD CONSTRAINT fk_zc_provider_action_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_provider_action
  ADD CONSTRAINT fk_zc_provider_action_participation FOREIGN KEY (tenant_id, participation_id)
    REFERENCES zc_provider_participation (tenant_id, id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_referral ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_referral FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_referral_tenant ON zc_referral
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_transition ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_transition FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_transition_tenant ON zc_transition
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_provider_participation ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_provider_participation FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_provider_participation_tenant ON zc_provider_participation
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_provider_action ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_provider_action FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_provider_action_tenant ON zc_provider_action
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_referral_tenant ON zc_referral;
ALTER TABLE zc_referral NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_referral DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_transition_tenant ON zc_transition;
ALTER TABLE zc_transition NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_transition DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_provider_participation_tenant ON zc_provider_participation;
ALTER TABLE zc_provider_participation NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_provider_participation DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_provider_action_tenant ON zc_provider_action;
ALTER TABLE zc_provider_action NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_provider_action DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_referral TO zc_app;
GRANT USAGE ON SEQUENCE zc_referral_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_transition TO zc_app;
GRANT USAGE ON SEQUENCE zc_transition_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_provider_participation TO zc_app;
GRANT USAGE ON SEQUENCE zc_provider_participation_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_provider_action TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_provider_action FROM zc_app;
GRANT USAGE ON SEQUENCE zc_provider_action_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_referral FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_referral_id_seq FROM zc_app;
REVOKE ALL ON zc_transition FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_transition_id_seq FROM zc_app;
REVOKE ALL ON zc_provider_participation FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_provider_participation_id_seq FROM zc_app;
REVOKE ALL ON zc_provider_action FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_provider_action_id_seq FROM zc_app;
